// ── Generic FAQ template — falls back when no per-slug override exists ───────

export function makeGenericFaqs(cityName) {
    return [
        {
            q: `How does Atlantis Digital Twin work in ${cityName}?`,
            a: `We start with a 3D scan of your asset (drone, laser, photogrammetry), build a CAD-fidelity model, and then overlay every NDT inspection event (UT thickness readings, TOFD/PAUT scans, MT/PT indications, RT defect maps). Inspection data updates the model in real-time and colour-codes condition zones for engineering review. Operators in ${cityName} use this to drive faster turnaround scoping, automated FFS evidence, and audit-grade regulatory reporting.`
        },
        {
            q: `What does Digital Twin NDT cost in ${cityName}?`,
            a: `Atlantis Digital Twin starts at USD 200,000/year for up to 500 assets, with ASNT Level III consulting and unlimited NDT data ingest included. Enterprise tiers are available for multi-site fleets, and on-prem deployment is offered at the same price point. Request a ${cityName}-specific quote and we will model your asset count and data-volume requirements.`
        },
        {
            q: `How long does deployment take in ${cityName}?`,
            a: `A typical first-asset deployment runs 8-12 weeks: 2 weeks model build, 2 weeks data integration, 2-4 weeks workflow configuration, 2 weeks user training. Multi-asset rollouts are sequenced asset-by-asset after the first deployment is live, with each subsequent asset typically taking 4-6 weeks once the platform is configured for your ${cityName} site.`
        },
        {
            q: `Which NDT standards does the platform support in ${cityName}?`,
            a: `API 510 (pressure vessels), API 570 (piping), API 653 (storage tanks), API 579 FFS, API 581 RBI, ASME Section V articles 2/4/6/7, ISO 9712 personnel qualification, ASNT SNT-TC-1A, and local code requirements depending on ${cityName}'s regulatory environment. Custom reporting templates can be configured for any additional national or operator-specific code.`
        },
        {
            q: `Can Atlantis Digital Twin integrate with our existing CMMS in ${cityName}?`,
            a: `Yes. We support REST API hooks for IBM Maximo, SAP PM, IFS, Oracle EAM, and most major CMMS platforms. Work-order creation, asset master sync, anomaly hand-off into corrective work, and FFS evidence packaging for management-of-change submittals can all be automated, allowing your ${cityName} integrity team to focus on engineering judgement rather than data entry.`
        }
    ];
}

// ── Lookup helper that prefers a per-slug override, otherwise generic ────────

export function getFaqsForCity(slug, cityName) {
    if (digitalTwinFaqsByCity[slug]) return digitalTwinFaqsByCity[slug];
    return makeGenericFaqs(cityName || slug);
}
